  const count=card.querySelector('.fp-count'),note=card.querySelector('.fp-note'),cta=card.querySelector('a');
  const countText=total+' bài đã đọc trong thư viện';if(count&&count.textContent!==countText)count.textContent=countText;
  const noteText='Theo lịch hôm nay: '+complete+'/'+ids.length+' bài'+(ahead?' · '+ahead+' bài đã đọc trước cho các ngày sau.':'.');if(note&&note.textContent!==noteText)note.textContent=noteText;
  const state=card.querySelector('.fp-state');if(state){const text=complete===ids.length?'Đã hoàn thành':'Cần hoàn thành';if(state.textContent!==text)state.textContent=text;}card.classList.toggle('is-done',complete===ids.length);
  const next=ids.find(id=>!checked(id));if(cta){const href=next?'knowledge.html#'+encodeURIComponent(next):'knowledge.html';if(cta.getAttribute('href')!==href)cta.setAttribute('href',href);}
