 if(msg.dataset.message!==text){msg.dataset.message=text;msg.replaceChildren();const p=document.createElement('p');p.textContent=text;msg.append(p);if(phase==='error'){const b=document.createElement('button');b.type='button';b.className='hub-button';b.textContent='Thử lại';b.dataset.kfTodayRetry='1';msg.append(b);}}
