 if(isKnowledge&&response.ok){
  const method=(init?.method||input?.method||'GET').toUpperCase();
  await response.clone().json().then(async data=>{
   if(method==='GET'){if(accept(data))queuePaint();return;}
   if(method!=='POST')return;
   let body;try{body=typeof init?.body==='string'?JSON.parse(init.body):await input.clone().json();}catch{return;}
   if(!body?.id||!body?.value)return;
   const scope=body.account_key||account;if(account&&scope&&scope!==account)return;
   const row={id:body.id,value:body.value,revision:data.revision};const old=records.get(row.id);if(old&&old.revision>row.revision)return;records.set(row.id,row);revisionSignature='';
   channel?.postMessage({accountKey:scope,row});queuePaint();
  }).catch(()=>{});
 }
