async function init(){if(!loaded)loaded=(async()=>{const state=await KStore.load();if(state.guest||!state.accountKey)return null;account=state.accountKey;const saved=await storage('readonly');disabled=saved?.disabled===true;if(saved?.plan&&!disabled){local=normalizePlan(validate(saved.plan));if(saved.plan.localGrammarPolicy!==local.localGrammarPolicy)await storage('readwrite',{...saved,plan:local,updatedAt:new Date().toISOString()});}return local;})().catch(e=>{loaded=null;throw e;});return loaded;}
async function save(plan){plan=normalizePlan(plan);validate(plan);await init();if(!account)throw Error('Cần đăng nhập để xác định lịch của tài khoản.');const record={schema:VERSION,accountKey:account,updatedAt:new Date().toISOString(),disabled:false,plan:clone(plan)};await storage('readwrite',record);local=record.plan;disabled=false;acceptNative?.(local);window.studyPlan=local;window.planUpdateError=null;return local;}
