document.addEventListener('submit',e=>{if(e.target.id!=='learning-plan-form')return;if(disabled&&!local)return;e.preventDefault();e.stopImmediatePropagation();rebuild(e.target.querySelector('[type=submit]'),true);},true);
document.addEventListener('click',async e=>{const grammarButton=e.target.closest('[data-kf-local-grammar]');if(grammarButton){e.preventDefault();e.stopImmediatePropagation();selectNativeGrammar(grammarButton.dataset.kfLocalGrammar);return;}const b=e.target.closest('[data-full-plan-build]');if(b&&!disabled){e.preventDefault();e.stopImmediatePropagation();rebuild(b,false);return;}const action=e.target.closest('[data-kflp]')?.dataset.kflp;if(!action)return;e.preventDefault();e.stopImmediatePropagation();try{await init();if(action==='edit'){disabled=false;KPlan.open(local?.band);return;}if(action==='backup'){if(!local)throw Error('Chưa có lịch trên thiết bị.');const payload={format:'khangflash-device-schedule',schema:VERSION,exportedAt:new Date().toISOString(),accountKey:account,plan:local};const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.href=url;a.download='khangflash-lich-hoc-'+local.start+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);note('Đã tạo tệp sao lưu lịch. Tệp này không chứa tiến độ học trên máy chủ.');}if(action==='server'){await storage('readwrite',{schema:VERSION,accountKey:account,disabled:true,plan:local});location.reload();}}catch(err){note(err.message);}},true);
document.addEventListener('change',async e=>{if(e.target.id!=='kf-local-plan-import')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Tệp vượt giới hạn 10 MB.');await init();const input=JSON.parse(await file.text());if(input.format!=='khangflash-device-schedule'||input.schema!==VERSION||input.accountKey!==account)throw Error('Tệp phải là lịch của đúng tài khoản hiện tại.');const plan=validate(input.plan);const {data}=context(),catalog=await FullPlan.load();const sets={cards:new Set(data.cards.map(c=>c.id)),reading:new Set(catalog.reading.map(c=>c.id)),writing:new Set(catalog.writing.map(c=>c.id))};for(const d of plan.days)for(const kind of ['cards','reading','writing'])for(const id of d[kind])if(!sets[kind].has(id))throw Error('Tệp có nội dung không còn trong thư viện; chưa thay đổi lịch.');await save(plan);message='Đã khôi phục lịch. Tiến độ học trên máy chủ được giữ nguyên.';redraw();}catch(err){note(err.message);}finally{e.target.value='';}});
let queued=false;function observe(){if(!document.body)return;if(/^\/(dashboard|schedule)(?:\.html)?\/?$/.test(location.pathname))new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(()=>{queued=false;paint();});}}).observe(document.body,{childList:true,subtree:true});paint();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',observe,{once:true});else observe();
