let bootAttempts=0,bootRunning=false;const boot=setInterval(async()=>{if(bootRunning)return;if(++bootAttempts>120){clearInterval(boot);return;}if(!window.KPlan||!window.KStore)return;bootRunning=true;try{await KPlan.load();if(local&&(syncVocabularyDay()||await mountGrammarDay())){clearInterval(boot);return;}if(typeof library==='undefined'||typeof stats==='undefined'||!library?.cards||!stats?.today)return;if(!window.FullPlan)return;clearInterval(boot);if(!local&&!disabled&&!stats.guest){await KPlan.ensureGoal(library,stats);}if(local){stats=KStore.get();window.studyPlan=local;window.planUpdateError=null;redraw();}else paint();}catch(err){clearInterval(boot);message=err.message;paint();}finally{bootRunning=false;}},250);
