 const paceCache=new WeakMap();let paceBoard=null;
 function tailPace(){
  const g=state();
  if(!g||g.phase!=='playing'||!Array.isArray(g.active))return;
  const board=paceBoard?.isConnected?paceBoard:(paceBoard=document.querySelector('.cb-board:not(.bb-board)'));
  if(!board||!g||g.phase!=='playing'||!Array.isArray(g.deck)||!Array.isArray(g.active))return;
  let cached=paceCache.get(g);const sig=g.deck.length+':'+(g.records||[]).length;
  if(!cached||cached.sig!==sig){const solved=new Set((g.records||[]).filter(r=>r.ok).map(r=>r.card?.id||r.cardId||r.id));cached={sig,remaining:new Set(g.deck.map(c=>c.id).filter(id=>!solved.has(id))).size};paceCache.set(g,cached);}
  const remaining=cached.remaining;
  if(remaining>5||remaining<1){if(board.hasAttribute('data-kf-tail-pace'))board.removeAttribute('data-kf-tail-pace');return;}
  const elapsed=Number(g.elapsed);
  if(!Number.isFinite(elapsed))return;
  const wait=g.active.length?550:180;
  if(Number.isFinite(g.spawnAt)&&g.spawnAt>elapsed+wait){g.spawnAt=elapsed+wait;if(board.dataset.kfSpawnWait!==String(wait))board.dataset.kfSpawnWait=String(wait);}
  const retryKeys=new Set();
  for(const r of g.retries||[]){
   if(!r||typeof r!=='object')continue;
   for(const key of ['at','readyAt','eligibleAt','availableAt','dueAt','ready','time']){
    if(!Number.isFinite(r[key]))continue;
    retryKeys.add(key);
    const now=r[key]>1e12?Date.now():elapsed;
    if(r[key]>now)r[key]=Math.min(r[key],now+650);
   }
  }
  if(board.dataset.kfTailPace!=='fast')board.dataset.kfTailPace='fast';
  if(board.dataset.kfTailRemaining!==String(remaining))board.dataset.kfTailRemaining=String(remaining);
  const shape=JSON.stringify((g.retries||[]).slice(0,2).map(r=>Object.keys(r)));if(board.dataset.kfRetryShape!==shape)board.dataset.kfRetryShape=shape;
 }
 let paceHook=null;
 function installPace(){
  const api=window.KFBeeMotion;if(!api||api===paceHook)return;paceHook=api;
  const original=api.paint;api.paint=function(){tailPace();return original.apply(this,arguments);};
 }
 function counterSnapshot(){
  const g=state();
  if(g&&Array.isArray(g.deck)&&g.deck.length){
   const records=Array.isArray(g.records)?g.records:[];
   const signature='blast:'+g.deck.length+':'+records.length+':'+g.score+':'+g.cursor;
   if(signature===lastCounter)return null;lastCounter=signature;
   const ids=new Set(g.deck.map(c=>c.id)),correct=new Set(),wrong=new Set();
   for(const r of records){const id=r.card?.id||r.cardId||r.id;if(!ids.has(id))continue;if(r.ok)correct.add(id);else wrong.add(id);}
   const result={total:ids.size,done:correct.size,correct:correct.size,wrong:wrong.size,remaining:Math.max(0,ids.size-correct.size)};lastStats=result;return result;
  }
  try{
   if(typeof sessionCards==='undefined'||!sessionCards.length)return null;
   const cards=sessionCards,done=typeof sessionDone!=='undefined'?sessionDone:new Set(),rows=new Map((window.KStore?.get?.().cards||[]).map(r=>[r.card_id,r]));
   const completed=cards.filter(c=>done.has(c.id)),correct=completed.filter(c=>rows.get(c.id)?.status==='known').length;
   const signature='session:'+cards.length+':'+completed.length+':'+correct;
   if(signature===lastCounter)return null;lastCounter=signature;
   const result={total:cards.length,done:completed.length,correct,wrong:completed.length-correct,remaining:cards.length-completed.length};lastStats=result;return result;
  }catch{return null;}
 }
