   text(note,'Còn '+stats.remaining+' / '+stats.total+' · Đúng '+stats.correct+' · Sai '+stats.wrong);
   for(const node of Array.from(button.querySelectorAll('small,span')))if(node!==note&&node.children.length===0&&/\d+[\s\S]*mục trong bộ/.test(node.textContent))node.hidden=true;
