      state.speedMultiplier = sp;
      if (state.currentItem) {
        state.fallDurationMs = computeFallDurationMs(state.currentItem, state.difficulty, state.speedMultiplier);
        state.fallElapsedMs = ratio * state.fallDurationMs;
        elAllowance.textContent = `⏱ ${(state.fallDurationMs / 1000).toFixed(1)}s`;
      }
