 const paras=item.paragraphs.map(p=>({part:p.label,why:p.focus,watch:p.flow,rewrite:p.en,rewriteWhy:'Bản gốc được giữ nguyên. Có thể tự rút gọn nhưng cần giữ các bước lập luận đã nêu.',steps:split(p.en).map(quote=>({quote,why:p.focus,check:'Câu này đóng góp gì vào mạch: '+p.flow+'?'}))}));
