 async function init(){root.innerHTML='<p class="w-loading">Đang tải bộ Task 2 có hướng dẫn…</p>';try{const [data]=await Promise.all([fetch('task2-bank/index.json?v=291').then(r=>{if(!r.ok)throw Error('Chưa tải được danh mục đề.');return r.json();}),P.load()]);bank=bridge.mergeBank(data);const id=params.get('task2');if(id){const stub=bank.lessons.find(l=>l.id===id);if(!stub)throw Error('Không tìm thấy bài.');lesson=bridge.converted.get(id);try{const tr=bridge.translation(id);if(tr.task2Source===lesson.id&&Array.isArray(tr.questions))translations=new Map(tr.questions.filter(q=>q.en&&q.vi).map(q=>[q.en,q.vi]));}catch{}const old=P.get(key());state=old?.version===bank.version&&old.questions?.length===2?structuredClone(old):fresh();state.step=Math.max(0,Math.min(3,state.step||0));renderLesson();}else hub();}catch(err){root.innerHTML=head()+`<main class="t2-wrap"><h1>Chưa mở được bài học</h1><p role="alert">${e(err.message)}</p><a href="${url()}" data-kf2-nav>Về danh mục Task 2</a></main>`;}}
 init();const previousFlush=window.Task2Course.flush;window.Task2Course.flush=async()=>{await previousFlush?.();await flush();};return{words,flush};
