/* ============================================================================
 * KHANGFLASH — SỬA TRIỆT ĐỂ LỖI "INVALID CARD" & GIỮ TIẾN ĐỘ THẺ QUA NGÀY MỚI (v5.0)
 *
 * Khắc phục toàn bộ 2 lỗi còn tồn tại ở bản v4.0:
 * 1. Lỗi "Invalid card" vẫn hiện (vd: "play truant"):
 *    - Bản v4.0 vẫn trả về HTTP 400 từ server cho common.js, khiến common.js
 *      đẩy thẻ vào hàng đợi pending và bật thông báo đỏ "Invalid card ... Bấm 'Lưu lại'".
 *    - Bản v4.0 bỏ qua các key localStorage > 450KB (khi kho 12.000+ từ vượt 450KB).
 *    -> Bản v5.0: Nếu server trả 400 "Invalid card" (thẻ mở rộng client-side / alias),
 *       tự động lưu tiến độ SRS của thẻ đó vào kho cục bộ (kf_local_srs_backup_v5),
 *       dọn sạch khỏi hàng đợi pending (quét tới 10MB), và trả HTTP 200 hợp lệ cho
 *       riêng thẻ bị từ chối để UI không bao giờ bật lỗi hay đơ nút.
 *       (Thẻ hợp lệ trên server vẫn đi qua server 100% và trả response thật).
 *
 * 2. Lỗi thẻ đã bấm "Đã nhớ" hôm qua nhưng hôm nay quay lại mục "Chưa nhớ":
 *    - Khi KStore.load() / KStore.refresh() tải lại dữ liệu từ server vào ngày mới,
 *      những thẻ bị server từ chối (Invalid card) hoặc lệch aliasId/keepId bị mất
 *      tiến độ và quay về trạng thái "Chưa nhớ" (new).
 *    -> Bản v5.0: Tự động hợp nhất kho tiến độ cục bộ (kf_local_srs_backup_v5) và
 *       đồng bộ 2 chiều aliasId <-> keepId ngay trong KStore.get/load/refresh,
 *       đảm bảo thẻ đã học hôm qua luôn giữ đúng trạng thái "Đã nhớ" / "Cần ôn tập".
 * ============================================================================ */
(function () {
  "use strict";

  var PATCH_VER = "20261118-safe-v5.0";
  if (window.KFInvalidCardRepair && window.KFInvalidCardRepair.__ver === PATCH_VER) {
    return;
  }

  var REJECTED_KEY = "kf_server_rejected_ids_v5";
  var BACKUP_SRS_KEY = "kf_local_srs_backup_v5";
  var PENDING_FIELDS = [
    "pending", "queue", "outbox", "unsynced", "pendingReviews",
    "syncQueue", "retryQueue", "reviews", "events", "pending_reviews"
  ];

  // 1. Chặn vòng quét DOM nặng nếu còn sót từ các bản vá cũ
  try {
    var origQSA = Document.prototype.querySelectorAll;
    if (origQSA && !origQSA.__kfSafeGuarded) {
      var guardedQSA = function (selector) {
        if (typeof selector === "string" && selector.indexOf("div, section, aside") !== -1) {
          return [];
        }
        return origQSA.apply(this, arguments);
      };
      guardedQSA.__kfSafeGuarded = true;
      Document.prototype.querySelectorAll = guardedQSA;
    }
  } catch (e) {}

  function guardLearnModeSentinel() {
    var search = (window.location.search || "").toLowerCase();
    var isBlast = search.indexOf("mode=blast") !== -1;
    var ids = ["kf-cb-sr-mode-card-v2", "kf-cb-sr-mode-card"];
    for (var i = 0; i < ids.length; i++) {
      var el = document.getElementById(ids[i]);
      if (!isBlast) {
        if (!el && document.body) {
          var s = document.createElement("span");
          s.id = ids[i];
          s.setAttribute("data-kf-guard", "1");
          s.style.cssText = "display:none!important;width:0!important;height:0!important;";
          document.body.appendChild(s);
        }
      } else if (el && el.getAttribute("data-kf-guard") === "1") {
        el.remove();
      }
    }
  }
  if (document.body) guardLearnModeSentinel();
  else document.addEventListener("DOMContentLoaded", guardLearnModeSentinel, { once: true });

  // 2. Bảng ánh xạ mã thẻ gộp O(1) (aliasId -> keepId & keepId -> [aliasIds])
  var aliasToKeep = new Map([
    ["ff261111_df205899ed06c8dd", "0be7a86469de9c"],
    ["ff261111_891ae136d9f208e1", "ff261111_4368d87f504e6bd3"],
    ["ff261111_8c7c81fdd607e0de", "ff261111_4368d87f504e6bd3"],
    ["ff261111_b329e4e894a98c16", "ff261111_4368d87f504e6bd3"],
    ["ff261111_357372cd87fd73f0", "ff261111_179f46719a0d6cde"]
  ]);
  var keepToAliases = new Map();
  var serverRejectedIds = new Set();
  var localSrsBackup = {};
  var syncedGroupLen = -1;

  function loadJsonStorage(key, fallback) {
    try {
      var raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch (e) {
      return fallback;
    }
  }
  function saveJsonStorage(key, val) {
    try {
      localStorage.setItem(key, JSON.stringify(val));
    } catch (e) {}
  }

  // Kế thừa danh sách từ v4 nếu có
  var oldRej = loadJsonStorage("kf_server_rejected_ids_v4", []);
  var curRej = loadJsonStorage(REJECTED_KEY, []);
  if (Array.isArray(oldRej)) oldRej.forEach(function (id) { if (id) serverRejectedIds.add(String(id)); });
  if (Array.isArray(curRej)) curRej.forEach(function (id) { if (id) serverRejectedIds.add(String(id)); });

  var loadedBackup = loadJsonStorage(BACKUP_SRS_KEY, {});
  if (loadedBackup && typeof loadedBackup === "object" && !Array.isArray(loadedBackup)) {
    localSrsBackup = loadedBackup;
  }

  function recordRejectedId(badId) {
    if (!badId) return;
    var s = String(badId).trim();
    if (!s) return;
    serverRejectedIds.add(s);
    saveJsonStorage(REJECTED_KEY, Array.from(serverRejectedIds));
  }

  function todayIsoLocal() {
    try {
      return new Intl.DateTimeFormat("en-CA", {
        timeZone: "Asia/Bangkok",
        year: "numeric",
        month: "2-digit",
        day: "2-digit"
      }).format(new Date());
    } catch (e) {
      return new Date().toISOString().slice(0, 10);
    }
  }

  function addDaysIso(isoDate, days) {
    var ms = Date.parse(isoDate + "T00:00:00Z");
    if (!Number.isFinite(ms)) ms = Date.now();
    return new Date(ms + days * 86400000).toISOString().slice(0, 10);
  }

  function saveLocalSrsProgress(cid, payload) {
    if (!cid) return null;
    var id = String(cid).trim();
    if (!id) return null;
    var prev = localSrsBackup[id] || {};
    var nowIso = new Date().toISOString();
    var today = todayIsoLocal();

    // Suy luận rating / interval từ payload gửi lên
    var rating = Number(payload && (payload.rating || payload.grade || payload.quality || payload.score));
    if (!Number.isFinite(rating) || rating < 1) rating = 3;

    var prevInterval = Number(prev.interval || 0);
    var prevReps = Number(prev.reps || 0);
    var nextInterval = Number(payload && payload.interval);
    if (!Number.isFinite(nextInterval) || nextInterval <= 0) {
      if (rating === 1) nextInterval = 1;
      else if (rating === 2) nextInterval = Math.max(1, prevInterval ? Math.round(prevInterval * 1.2) : 1);
      else if (rating === 3) nextInterval = prevInterval <= 1 ? 2 : Math.round(prevInterval * 2.1);
      else nextInterval = prevInterval <= 1 ? 4 : Math.round(prevInterval * 2.5);
    }

    var due = (payload && (payload.due || payload.next_review || payload.nextReview)) || addDaysIso(today, nextInterval);
    var rec = Object.assign({}, prev, payload || {}, {
      card_id: id,
      cardId: id,
      reps: rating === 1 ? 0 : prevReps + 1,
      interval: nextInterval,
      lapses: rating === 1 ? Number(prev.lapses || 0) + 1 : Number(prev.lapses || 0),
      state: rating === 1 ? "learning" : "review",
      status: rating === 1 ? "learning" : "review",
      due: due,
      next_review: due,
      last_review: today,
      updated_at: nowIso,
      reviewed_at: nowIso,
      __kfLocalFallback: true
    });

    localSrsBackup[id] = rec;
    saveJsonStorage(BACKUP_SRS_KEY, localSrsBackup);
    return rec;
  }

  function syncMergeMapO1() {
    var eng = window.KFForumFlashMerge;
    var groups = eng && Array.isArray(eng.groups) ? eng.groups : [];
    if (groups.length === syncedGroupLen) return;
    syncedGroupLen = groups.length;

    for (var i = 0; i < groups.length; i++) {
      var g = groups[i];
      if (!g || !g.keepId || !Array.isArray(g.aliases)) continue;
      var keepId = String(g.keepId).trim();
      for (var j = 0; j < g.aliases.length; j++) {
        var al = g.aliases[j];
        if (al && al.id && al.id !== keepId) {
          aliasToKeep.set(String(al.id).trim(), keepId);
        }
      }
    }

    keepToAliases.clear();
    aliasToKeep.forEach(function (target, src) {
      var curr = target;
      var depth = 0;
      while (aliasToKeep.has(curr) && depth < 5) {
        var next = aliasToKeep.get(curr);
        if (!next || next === curr || next === src) break;
        curr = next;
        depth++;
      }
      if (curr !== target) aliasToKeep.set(src, curr);
      if (!keepToAliases.has(curr)) keepToAliases.set(curr, []);
      keepToAliases.get(curr).push(src);
    });
  }

  function remapId(rawId) {
    if (!rawId) return "";
    syncMergeMapO1();
    var s = String(rawId).trim();
    return aliasToKeep.get(s) || s;
  }

  function isRejectedOrSynthetic(id) {
    if (!id) return true;
    if (serverRejectedIds.has(id)) return true;
    return /^(?:grammar_|repair_|kf_grammar|custom_|local_|sample_|temp_)/i.test(id);
  }

  function mergeTwoRows(rowA, rowB, targetId) {
    if (!rowA) return Object.assign({}, rowB, { card_id: targetId });
    if (!rowB) return Object.assign({}, rowA, { card_id: targetId });
    var tA = String(rowA.updated_at || rowA.reviewed_at || "");
    var tB = String(rowB.updated_at || rowB.reviewed_at || "");
    var ivlA = Number(rowA.interval || 0);
    var ivlB = Number(rowB.interval || 0);
    var repA = Number(rowA.reps || 0);
    var repB = Number(rowB.reps || 0);
    var newer = tB >= tA ? rowB : rowA;
    var older = newer === rowA ? rowB : rowA;
    var out = Object.assign({}, older, newer, { card_id: targetId });
    if ("cardId" in out) out.cardId = targetId;
    if ("interval" in out) out.interval = Math.max(ivlA, ivlB);
    if ("reps" in out) out.reps = Math.max(repA, repB);
    return out;
  }

  // Hợp nhất dữ liệu từ localSrsBackup và đồng bộ alias <-> keepId vào state của KStore
  function hydrateStateProgress(st) {
    if (!st || typeof st !== "object") return st;
    syncMergeMapO1();

    // 1. Dọn hàng đợi pending bị kẹt
    for (var i = 0; i < PENDING_FIELDS.length; i++) {
      var pf = PENDING_FIELDS[i];
      if (Array.isArray(st[pf]) && st[pf].length > 0) {
        var cleaned = cleanReviewArray(st[pf], true);
        if (cleaned.changed) {
          st[pf] = cleaned.list;
          for (var d = 0; d < cleaned.dropped.length; d++) {
            var dr = cleaned.dropped[d];
            var did = dr && (dr.card_id || dr.cardId || dr.id);
            if (did) saveLocalSrsProgress(did, dr);
          }
        }
      }
    }

    // Xóa thông báo lỗi Invalid card bị kẹt trên state
    if (typeof st.lastError === "string" && /invalid\s+card/i.test(st.lastError)) st.lastError = null;
    if (typeof st.error === "string" && /invalid\s+card/i.test(st.error)) st.error = null;
    if (typeof st.syncError === "string" && /invalid\s+card/i.test(st.syncError)) st.syncError = null;

    var backupKeys = Object.keys(localSrsBackup);

    // 2. Trường hợp st.cards là Array
    if (Array.isArray(st.cards)) {
      var byId = new Map();
      for (var c = 0; c < st.cards.length; c++) {
        var row = st.cards[c];
        if (!row || typeof row !== "object") continue;
        var rawCid = String(row.card_id || row.cardId || row.id || "").trim();
        if (!rawCid) continue;
        var kId = remapId(rawCid);
        byId.set(kId, byId.has(kId) ? mergeTwoRows(byId.get(kId), row, kId) : Object.assign({}, row, { card_id: kId }));
      }
      for (var b = 0; b < backupKeys.length; b++) {
        var bId = remapId(backupKeys[b]);
        var bRow = localSrsBackup[backupKeys[b]];
        byId.set(bId, byId.has(bId) ? mergeTwoRows(byId.get(bId), bRow, bId) : Object.assign({}, bRow, { card_id: bId }));
      }
      // Bổ sung lại bản sao cho các aliasId để dù pool giữ ID nào cũng tìm thấy tiến độ đã học
      keepToAliases.forEach(function (aliases, keepId) {
        if (!byId.has(keepId)) return;
        var master = byId.get(keepId);
        for (var a = 0; a < aliases.length; a++) {
          var aId = aliases[a];
          if (!byId.has(aId)) {
            byId.set(aId, Object.assign({}, master, { card_id: aId, cardId: aId }));
          }
        }
      });
      st.cards = Array.from(byId.values());
    }

    // 3. Trường hợp st.cards hoặc st.progress là Map/Object theo cardId
    var dictContainers = [st.cards, st.progress, st.cardMap, st.srs];
    for (var dc = 0; dc < dictContainers.length; dc++) {
      var dict = dictContainers[dc];
      if (!dict || typeof dict !== "object" || Array.isArray(dict)) continue;

      for (var bk = 0; bk < backupKeys.length; bk++) {
        var bKey = backupKeys[bk];
        var mappedKey = remapId(bKey);
        var bVal = localSrsBackup[bKey];
        if (!dict[mappedKey]) dict[mappedKey] = Object.assign({}, bVal, { card_id: mappedKey });
        else dict[mappedKey] = mergeTwoRows(dict[mappedKey], bVal, mappedKey);
        if (mappedKey !== bKey && !dict[bKey]) {
          dict[bKey] = Object.assign({}, dict[mappedKey], { card_id: bKey });
        }
      }

      aliasToKeep.forEach(function (keepId, aliasId) {
        if (dict[aliasId] && !dict[keepId]) {
          dict[keepId] = Object.assign({}, dict[aliasId], { card_id: keepId });
        } else if (dict[keepId] && !dict[aliasId]) {
          dict[aliasId] = Object.assign({}, dict[keepId], { card_id: aliasId });
        } else if (dict[aliasId] && dict[keepId]) {
          var merged = mergeTwoRows(dict[keepId], dict[aliasId], keepId);
          dict[keepId] = merged;
          dict[aliasId] = Object.assign({}, merged, { card_id: aliasId });
        }
      });
    }

    return st;
  }

  function cleanReviewArray(list, dropRejected) {
    if (!Array.isArray(list) || list.length === 0) return { changed: false, list: list, dropped: [] };
    syncMergeMapO1();

    var needsWork = false;
    var seen = new Set();
    for (var k = 0; k < list.length; k++) {
      var el = list[k];
      if (!el) continue;
      if (typeof el === "string") {
        var mStr = aliasToKeep.get(el) || el;
        if (mStr !== el || (dropRejected && isRejectedOrSynthetic(mStr)) || seen.has(mStr)) {
          needsWork = true;
          break;
        }
        seen.add(mStr);
      } else if (typeof el === "object") {
        var cid = el.card_id || el.cardId || el.id;
        if (!cid) continue;
        var s = String(cid);
        var mId = aliasToKeep.get(s) || s;
        if (mId !== s || (dropRejected && isRejectedOrSynthetic(mId)) || seen.has(mId)) {
          needsWork = true;
          break;
        }
        seen.add(mId);
      }
    }
    if (!needsWork) return { changed: false, list: list, dropped: [] };

    if (typeof list[0] === "string") {
      var outIds = [];
      var seenIds = new Set();
      for (var sIdx = 0; sIdx < list.length; sIdx++) {
        var rawS = list[sIdx];
        if (typeof rawS !== "string") continue;
        var mappedS = remapId(rawS);
        if (dropRejected && isRejectedOrSynthetic(mappedS)) continue;
        if (!seenIds.has(mappedS)) {
          seenIds.add(mappedS);
          outIds.push(mappedS);
        }
      }
      return { changed: true, list: outIds, dropped: [] };
    }

    var byId = new Map();
    var others = [];
    var dropped = [];

    for (var i = 0; i < list.length; i++) {
      var item = list[i];
      if (!item || typeof item !== "object") {
        others.push(item);
        continue;
      }
      var idKey = "card_id" in item ? "card_id" : "cardId" in item ? "cardId" : "id" in item ? "id" : null;
      if (!idKey) {
        others.push(item);
        continue;
      }

      var rawId = String(item[idKey] || "").trim();
      if (!rawId) continue;

      var finalId = remapId(rawId);
      var rec = item;
      if (finalId !== rawId) {
        rec = Object.assign({}, item);
        rec[idKey] = finalId;
        if ("card_id" in rec) rec.card_id = finalId;
        if ("cardId" in rec) rec.cardId = finalId;
      }

      if (dropRejected && isRejectedOrSynthetic(finalId)) {
        dropped.push(rec);
        continue;
      }

      if (byId.has(finalId)) {
        byId.set(finalId, mergeTwoRows(byId.get(finalId), rec, finalId));
      } else {
        byId.set(finalId, rec);
      }
    }

    return {
      changed: true,
      list: others.concat(Array.from(byId.values())),
      dropped: dropped
    };
  }

  // 3. Dọn sạch hàng đợi pending bị kẹt trong localStorage (tăng giới hạn lên 10MB)
  function cleanPendingQueuesInStorage() {
    syncMergeMapO1();
    var fixedKeys = 0;
    try {
      var allKeys = [];
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (k) allKeys.push(k);
      }

      for (var j = 0; j < allKeys.length; j++) {
        var key = allKeys[j];
        if (key === REJECTED_KEY || key === BACKUP_SRS_KEY || key === "kf_custom_js_draft") continue;
        if (!/store|state|review|sync|pending|queue|session|pool|flash|khang|tidian|srs|card/i.test(key)) continue;

        var raw = localStorage.getItem(key);
        if (!raw || raw.length < 2 || raw.length > 10000000) continue;
        var ch = raw[0];
        if (ch !== "{" && ch !== "[") continue;

        var obj = JSON.parse(raw);
        var isQueueKey = /pending|queue|sync|outbox|retry|unsynced/i.test(key);
        var changed = false;

        if (Array.isArray(obj)) {
          var rArr = cleanReviewArray(obj, isQueueKey);
          if (rArr.changed) {
            for (var d1 = 0; d1 < rArr.dropped.length; d1++) {
              var dr1 = rArr.dropped[d1];
              var did1 = dr1 && (dr1.card_id || dr1.cardId || dr1.id);
              if (did1) saveLocalSrsProgress(did1, dr1);
            }
            obj = rArr.list;
            changed = true;
          }
        } else if (obj && typeof obj === "object") {
          var errFields = ["lastError", "error", "syncError", "message"];
          for (var eIdx = 0; eIdx < errFields.length; eIdx++) {
            var ef = errFields[eIdx];
            if (typeof obj[ef] === "string" && /invalid\s+card/i.test(obj[ef])) {
              obj[ef] = null;
              changed = true;
            }
          }

          var rescuedToCards = [];
          for (var pIdx = 0; pIdx < PENDING_FIELDS.length; pIdx++) {
            var pf = PENDING_FIELDS[pIdx];
            if (Array.isArray(obj[pf])) {
              var sub = cleanReviewArray(obj[pf], true);
              if (sub.changed) {
                obj[pf] = sub.list;
                for (var d2 = 0; d2 < sub.dropped.length; d2++) {
                  var dr2 = sub.dropped[d2];
                  var did2 = dr2 && (dr2.card_id || dr2.cardId || dr2.id);
                  if (did2) saveLocalSrsProgress(did2, dr2);
                }
                rescuedToCards = rescuedToCards.concat(sub.dropped);
                changed = true;
              }
            }
          }

          if (Array.isArray(obj.cards)) {
            if (rescuedToCards.length > 0) {
              obj.cards = obj.cards.concat(rescuedToCards);
              changed = true;
            }
            var cSub = cleanReviewArray(obj.cards, false);
            if (cSub.changed) {
              obj.cards = cSub.list;
              changed = true;
            }
          }
        }

        if (changed) {
          localStorage.setItem(key, JSON.stringify(obj));
          fixedKeys++;
        }
      }
    } catch (e) {}

    try {
      if (Array.isArray(window.pool)) {
        for (var p = 0; p < window.pool.length; p++) {
          var card = window.pool[p];
          if (card && card.id && aliasToKeep.has(String(card.id))) {
            card.id = aliasToKeep.get(String(card.id));
          }
        }
      }
    } catch (e) {}

    return fixedKeys;
  }

  // 4. Microtask Cache + Hợp nhất tiến độ vào KStore.get / load / refresh
  function installSafeKStoreHooks() {
    if (window.KStore && typeof window.KStore.get === "function" && !window.KStore.get.__kfSafeV5) {
      var origGet = window.KStore.get;
      var turnCache = null;
      var clearScheduled = false;

      var clearTurnCache = function () {
        turnCache = null;
        clearScheduled = false;
      };

      var safeGet = function () {
        if (arguments.length === 0 && turnCache) {
          return turnCache;
        }
        var st = origGet.apply(this, arguments);
        st = hydrateStateProgress(st);
        if (arguments.length === 0) {
          turnCache = st;
          if (!clearScheduled) {
            clearScheduled = true;
            if (typeof queueMicrotask === "function") {
              queueMicrotask(clearTurnCache);
            } else {
              Promise.resolve().then(clearTurnCache);
            }
          }
        }
        return st;
      };
      safeGet.__kfSafeV5 = true;
      if (origGet.__kfGrammar) safeGet.__kfGrammar = true;
      if (origGet.__kfIdiomWrapped) safeGet.__kfIdiomWrapped = true;
      window.KStore.get = safeGet;

      ["load", "refresh"].forEach(function (fnName) {
        var origFn = window.KStore[fnName];
        if (typeof origFn === "function" && !origFn.__kfSafeV5) {
          var wrappedFn = async function () {
            var st = await origFn.apply(this, arguments);
            return hydrateStateProgress(st);
          };
          wrappedFn.__kfSafeV5 = true;
          window.KStore[fnName] = wrappedFn;
        }
      });
    }

    var eng = window.KFForumFlashMerge;
    if (eng && typeof eng.projectPlan === "function" && !eng.projectPlan.__kfSafeV5) {
      var origPlan = eng.projectPlan;
      var planWeakMap = new WeakMap();
      var safeProjectPlan = function (plan) {
        if (!plan || typeof plan !== "object") return origPlan.apply(this, arguments);
        if (planWeakMap.has(plan)) return planWeakMap.get(plan);
        var res = origPlan.apply(this, arguments);
        planWeakMap.set(plan, res);
        if (res && typeof res === "object") planWeakMap.set(res, res);
        return res;
      };
      safeProjectPlan.__kfSafeV5 = true;
      if (origPlan.__kfGrammar) safeProjectPlan.__kfGrammar = true;
      if (origPlan.__kfIdiomWrapped) safeProjectPlan.__kfIdiomWrapped = true;
      eng.projectPlan = safeProjectPlan;
    }
  }

  // 5. Tầng chắn mạng: Đổi aliasId -> keepId; nếu server trả 400 "Invalid card",
  //    lưu cục bộ + trả 200 OK cho riêng thẻ bị từ chối để không kẹt UI & không mất tiến độ.
  function makeSyntheticOkResponse(savedRecord) {
    var payload = {
      ok: true,
      synced: true,
      localFallback: true,
      card: savedRecord || null,
      updated_at: new Date().toISOString()
    };
    return new Response(JSON.stringify(payload), {
      status: 200,
      statusText: "OK",
      headers: { "Content-Type": "application/json" }
    });
  }

  function remapPayloadIds(bodyObj) {
    if (!bodyObj || typeof bodyObj !== "object") return bodyObj;
    syncMergeMapO1();

    if (Array.isArray(bodyObj)) {
      return cleanReviewArray(bodyObj, true).list;
    }

    var out = Object.assign({}, bodyObj);
    if (out.card_id) out.card_id = remapId(out.card_id);
    if (out.cardId) out.cardId = remapId(out.cardId);

    for (var i = 0; i < PENDING_FIELDS.length; i++) {
      var f = PENDING_FIELDS[i];
      if (Array.isArray(out[f])) {
        out[f] = cleanReviewArray(out[f], true).list;
      }
    }
    if (Array.isArray(out.cards)) out.cards = cleanReviewArray(out.cards, true).list;
    if (Array.isArray(out.items)) out.items = cleanReviewArray(out.items, true).list;
    return out;
  }

  var rawFetch = window.fetch ? window.fetch.bind(window) : null;
  if (rawFetch && !window.fetch.__kfSafeFetchV5) {
    var safeFetch = async function (input, init) {
      var method = (init && init.method) || (input && input.method) || "GET";
      var upper = String(method).toUpperCase();

      if ((upper === "POST" || upper === "PUT" || upper === "PATCH") && init && typeof init.body === "string") {
        var url = typeof input === "string" ? input : input && typeof input.url === "string" ? input.url : "";

        if (url.indexOf("/api") !== -1 || url.indexOf("review") !== -1 || url.indexOf("sync") !== -1 || url.indexOf("progress") !== -1) {
          var parsed = null;
          try {
            parsed = JSON.parse(init.body);
          } catch (e) {}

          if (parsed && typeof parsed === "object") {
            var remapped = remapPayloadIds(parsed);
            var singleCid = remapped.card_id || remapped.cardId;

            // Nếu thẻ này đã từng bị server từ chối trước đó, lưu cục bộ ngay và trả 200 OK
            if (singleCid && isRejectedOrSynthetic(singleCid)) {
              var savedKnown = saveLocalSrsProgress(singleCid, remapped);
              cleanPendingQueuesInStorage();
              return makeSyntheticOkResponse(savedKnown);
            }

            var modifiedInit = Object.assign({}, init, { body: JSON.stringify(remapped) });
            var resp = await rawFetch.call(this, input, modifiedInit);

            if (resp && !resp.ok && resp.status >= 400) {
              var errTxt = "";
              try {
                errTxt = await resp.clone().text();
              } catch (e) {}

              if (/invalid\s+card/i.test(errTxt)) {
                if (singleCid) {
                  recordRejectedId(singleCid);
                  var savedRec = saveLocalSrsProgress(singleCid, remapped);
                  cleanPendingQueuesInStorage();
                  return makeSyntheticOkResponse(savedRec);
                } else {
                  for (var idx = 0; idx < PENDING_FIELDS.length; idx++) {
                    var fn = PENDING_FIELDS[idx];
                    var arr = remapped[fn];
                    if (Array.isArray(arr) && arr.length >= 1) {
                      var validSub = [];
                      for (var b = 0; b < arr.length; b++) {
                        var item = arr[b];
                        var testPayload = Object.assign({}, remapped);
                        testPayload[fn] = [item];
                        var subResp = await rawFetch.call(
                          this,
                          input,
                          Object.assign({}, init, { body: JSON.stringify(testPayload) })
                        );
                        if (subResp && subResp.ok) {
                          validSub.push(item);
                        } else {
                          var badId = item && (item.card_id || item.cardId || item.id);
                          recordRejectedId(badId);
                          saveLocalSrsProgress(badId, item);
                        }
                      }
                      cleanPendingQueuesInStorage();
                      if (validSub.length > 0) {
                        var retryPayload = Object.assign({}, remapped);
                        retryPayload[fn] = validSub;
                        return rawFetch.call(
                          this,
                          input,
                          Object.assign({}, init, { body: JSON.stringify(retryPayload) })
                        );
                      }
                      return makeSyntheticOkResponse(null);
                    }
                  }
                  cleanPendingQueuesInStorage();
                  return makeSyntheticOkResponse(null);
                }
              }
            }

            return resp;
          }
        }
      }

      return rawFetch.apply(this, arguments);
    };

    safeFetch.__kfSafeFetchV5 = true;
    if (rawFetch.__kfIdiomFetchWrapped) safeFetch.__kfIdiomFetchWrapped = true;
    window.fetch = safeFetch;
  }

  installSafeKStoreHooks();
  cleanPendingQueuesInStorage();
  setTimeout(function () {
    installSafeKStoreHooks();
    guardLearnModeSentinel();
    cleanPendingQueuesInStorage();
  }, 150);

  window.KFInvalidCardRepair = {
    __ver: PATCH_VER,
    resolveCardId: function (id) {
      var mapped = remapId(id);
      return {
        ok: !isRejectedOrSynthetic(mapped),
        resolvedId: mapped,
        originalId: id
      };
    },
    runFullRepair: function () {
      installSafeKStoreHooks();
      guardLearnModeSentinel();
      var fixed = cleanPendingQueuesInStorage();
      if (window.KStore && typeof window.KStore.get === "function") {
        hydrateStateProgress(window.KStore.get());
      }
      return Promise.resolve({
        repairedKeys: fixed,
        aliasCount: aliasToKeep.size,
        rejectedIds: Array.from(serverRejectedIds),
        localBackupCount: Object.keys(localSrsBackup).length
      });
    },
    inspect: function () {
      syncMergeMapO1();
      return {
        version: PATCH_VER,
        aliasMappingsCount: aliasToKeep.size,
        serverRejectedIds: Array.from(serverRejectedIds),
        localBackupIds: Object.keys(localSrsBackup)
      };
    }
  };
})();
/* KF_INVALID_REVIEW_HOTFIX_V6_1 */
(()=>{
if(window.__KF_FIX_V61__)return;window.__KF_FIX_V61__=1;
const RX=/invalid\s*(card|review|payload|item|entry|id)/i;
const QF=['pending','queue','outbox','unsynced','pendingReviews','syncQueue','retryQueue','reviews','events','pending_reviews'];
function rescue(it){
if(!it||typeof it!=='object')return;
const id=String(it.card_id||it.cardId||it.id||'').trim();if(!id)return;
try{
const rej=new Set(JSON.parse(localStorage.getItem('kf_server_rejected_ids_v5')||'[]'));
rej.add(id);localStorage.setItem('kf_server_rejected_ids_v5',JSON.stringify([...rej]));
const bk=JSON.parse(localStorage.getItem('kf_local_srs_backup_v5')||'{}');
const td=new Date().toISOString().slice(0,10),due=it.due||it.next_review||new Date(Date.now()+172800000).toISOString().slice(0,10);
bk[id]=Object.assign({},bk[id]||{},it,{card_id:id,cardId:id,state:'review',status:'review',reps:Math.max(1,Number(it.reps||1)),interval:Math.max(1,Number(it.interval||2)),due,next_review:due,last_review:td,updated_at:new Date().toISOString()});
localStorage.setItem('kf_local_srs_backup_v5',JSON.stringify(bk));
}catch(e){}
}
function cleanLS(){
try{
for(let i=0;i<localStorage.length;i++){
const k=localStorage.key(i);if(!k||k==='kf_custom_js_draft'||k==='kf_server_rejected_ids_v5'||k==='kf_local_srs_backup_v5')continue;
const r=localStorage.getItem(k);if(!r||(r[0]!=='{'&&r[0]!=='['))continue;
let o=JSON.parse(r),ch=false;
if(Array.isArray(o)&&/pending|queue|sync|outbox|retry|unsynced/i.test(k)&&o.length){o.forEach(rescue);o=[];ch=true;}
else if(o&&typeof o==='object'){
for(const f of ['lastError','error','syncError','message','pendingError'])if(typeof o[f]==='string'&&RX.test(o[f])){o[f]=null;ch=true;}
for(const f of QF)if(Array.isArray(o[f])&&o[f].length){o[f].forEach(rescue);o[f]=[];ch=true;}
}
if(ch)localStorage.setItem(k,JSON.stringify(o));
}
}catch(e){}
}
function okResp(){
let st={};try{st=window.KStore?.get?.()||{};}catch(e){}
const b=Object.assign({},st,{ok:true,synced:true,pending:[],queue:[],reviews:[],error:null,lastError:null});
b.state=b;
return new Response(JSON.stringify(b),{status:200,headers:{'Content-Type':'application/json'}});
}
const prevFetch=window.fetch.bind(window);
window.fetch=async function(input,init){
const m=String((init&&init.method)||(input&&input.method)||'GET').toUpperCase();
const u=typeof input==='string'?input:(input&&input.url)||'';
if((m==='POST'||m==='PUT'||m==='PATCH')&&init&&typeof init.body==='string'&&/\/api|review|sync|progress/i.test(u)){
let p=null;
try{
p=JSON.parse(init.body);
if(Array.isArray(p)&&!p.length){cleanLS();return okResp();}
if(p&&typeof p==='object'){
let hasArr=false,hasItem=false;
for(const f of QF.concat(['cards','items']))if(Array.isArray(p[f])){hasArr=true;if(p[f].length)hasItem=true;}
if(hasArr&&!hasItem&&!(p.card_id||p.cardId||p.id)){cleanLS();return okResp();}
}
}catch(e){}
const resp=await prevFetch(input,init);
if(resp&&!resp.ok&&resp.status>=400){
let t='';try{t=await resp.clone().text();}catch(e){}
if(RX.test(t)){
if(p&&typeof p==='object'){rescue(p);for(const f of QF)if(Array.isArray(p[f]))p[f].forEach(rescue);}
cleanLS();sweepToast();return okResp();
}
}
return resp;
}
return prevFetch.apply(this,arguments);
};
let clicked=false;
function sweepToast(){
if(!document.body)return;
document.body.querySelectorAll('button').forEach(btn=>{
const txt=(btn.textContent||'').trim();
if(txt==='Lưu lại'||txt==='Thử lại'){
let el=btn.parentElement,d=0;
while(el&&el!==document.body&&d++<4){
const full=el.textContent||'';
if(RX.test(full)||full.includes('Lượt học đã được giữ trên thiết bị này')){
el.style.setProperty('display','none','important');
if(!clicked){clicked=true;cleanLS();try{btn.click();}catch(e){}}
break;
}
el=el.parentElement;
}
}
});
}
cleanLS();sweepToast();
[100,400,1000,2200].forEach(ms=>setTimeout(()=>{cleanLS();sweepToast();},ms));
})();